from test_bufftap import test,tests
from test_situations import setup
from test_blessings import setup as paladin

def case(name,code):test(name,setup+code)
case('Existing group settings remain the legacy fallback until edited',"assert(B:GroupSettings('Party')==B.db and B:GroupSettings('Raid')==B.db); B.db.groupNeed=4; assert(B:GroupPreference('groupNeed','Party')==4 and B:GroupPreference('groupNeed','Raid')==4)")
case('First group edit preserves existing values in both contexts',"B.db.group=true; B.db.groupNeed=4; B.db.buffClasses.thorns={WARRIOR=true,MAGE=false}; B:Options(); B.options.groupRaid.scripts.OnClick(); B:GroupEditorSettings().groupNeed=2; assert(B:GroupPreference('groupNeed','Party')==4 and B:GroupPreference('groupNeed','Raid')==2 and B:GroupPreference('group','Party')); assert(B:GroupPreference('buffClasses','Party').thorns.MAGE==false)")
case('Party and Raid settings share no nested maps',"B.db.buffGroups.motw={true,false,true,true,true,true,true,true}; B:GroupSettings('Party',true).group=true; local p=B:GroupSettings('Party'); local r=B:GroupSettings('Raid'); assert(p~=r and p.buffGroups~=r.buffGroups and p.buffGroups.motw~=r.buffGroups.motw); p.buffGroups.motw[2]=true; assert(r.buffGroups.motw[2]==false)")
case('Both group contexts remain independent from Solo settings',"B:GroupSettings('Party',true).groupNeed=4; B.db.groupNeed=2; assert(B:GroupPreference('groupNeed','Party')==4 and B:GroupPreference('groupNeed','Raid')==3)")
case('Editing Raid while Solo does not activate it',"B:Options(); B.options.groupRaid.scripts.OnClick(); B:GroupEditorSettings().group=false; assert(B.situationCurrent=='solo' and B:EditingGroupContext()=='Raid' and B:GroupPreference('group','Party')==false and B.action.id==5232)")
case('Party and Raid group enablement switches automatically',"B:GroupSettings('Party',true).group=false; B:GroupSettings('Raid',true).group=true; context='party'; refresh(); assert(not B:GroupPreference('group')); context='raid'; refresh(); assert(B:GroupPreference('group')); context='party'; refresh(); assert(not B:GroupPreference('group'))")
case('Party and Raid class recipient filters switch automatically',"B:GroupSettings('Party',true).buffClasses.thorns={WARRIOR=false}; B:GroupSettings('Raid',true).buffClasses.thorns={WARRIOR=true}; context='party'; refresh(); assert(not B:GroupClassAllowed(B:FindBuff('thorns'),'WARRIOR')); context='raid'; refresh(); assert(B:GroupClassAllowed(B:FindBuff('thorns'),'WARRIOR'))")
case('Per-buff thresholds stay independent',"B:SetGroupNeed(B:FindBuff('gotw'),4,'Party'); B:SetGroupNeed(B:FindBuff('gotw'),2,'Raid'); assert(B:GroupNeed(B:FindBuff('gotw'),'Party')==4 and B:GroupNeed(B:FindBuff('gotw'),'Raid')==2)")
case('Party hides raid-only group controls',"B:Options(); local f=B.options; assert(f.groupChecks[1].shown and f.groupChecks[1].Text.text=='Include party'); for i=2,8 do assert(not f.groupChecks[i].shown) end; assert(not f.assignRows[1].checks[2].shown); f.groupRaid.scripts.OnClick(); for i=1,8 do assert(f.groupChecks[i].shown) end; assert(f.assignRows[1].checks[8].shown)")
case('Party inclusion changes only Party recipients',"B:Options(); local c=B.options.groupChecks[1]; c:SetChecked(false); c.scripts.OnClick(c); assert(not B:GroupSelected(B:FindBuff('motw'),1,'Party') and B:GroupSelected(B:FindBuff('motw'),1,'Raid'))")
case('Recipient map edits preserve other class choices',"B:Options(); local row; for _,r in ipairs(B.options.assignRows) do if r.def.key=='thorns' then row=r end end; local c=row.classes.MAGE; c:SetChecked(true); c.scripts.OnClick(c); c=row.classes.WARLOCK; c:SetChecked(true); c.scripts.OnClick(c); local map=B:GroupPreference('buffClasses','Party').thorns; assert(map.MAGE and map.WARLOCK and B:GroupPreference('buffClasses','Raid').thorns==nil)")
case('Shared profile switching preserves both group contexts',"B:GroupSettings('Party',true).groupNeed=4; B:GroupSettings('Raid',true).groupNeed=2; B:CreateSettingsProfile('Other',false); assert(B:GroupPreference('groupNeed','Party')==4 and B:GroupPreference('groupNeed','Raid')==2)")
case('Explicit same-class profile copy includes group contexts',"B:GroupSettings('Party',true).groupNeed=4; B:GroupSettings('Raid',true).groupNeed=2; B:SaveClassSetup(); local source=B.profileDB:GetCurrentProfile(); local char=B.profileDB.keys.char; B:CreateSettingsProfile('Other',false); B:GroupSettings('Party',true).groupNeed=3; assert(B:CopySettingsProfile(source,char)); assert(B:GroupPreference('groupNeed','Party')==4 and B:GroupPreference('groupNeed','Raid')==2); B:GroupSettings('Party',true).groupNeed=5; assert(B.profileDB.global.characterSetups[source][char].settings.groupContextSettings.Party.groupNeed==4)")
case('Shared-only copying keeps current group contexts',"local source=B.profileDB:GetCurrentProfile(); B:CreateSettingsProfile('Other',false); B:GroupSettings('Party',true).groupNeed=4; assert(B:CopySettingsProfile(source)); assert(B:GroupPreference('groupNeed','Party')==4)")
case('Normalization preserves both contexts and rejects malformed filters',"B:GroupSettings('Party',true).buffClasses.thorns={WARRIOR=false,BAD=true}; B:GroupSettings('Raid',true).groupNeed=999; B:InitDB(); assert(B:GroupPreference('buffClasses','Party').thorns.WARRIOR==false and not B:GroupPreference('buffClasses','Party').thorns.BAD and B:GroupPreference('groupNeed','Raid')==5)")
case('Read paths reuse context tables without API polling',"B:GroupSettings('Party',true).groupNeed=4; context='party'; refresh(); local p=B:GroupSettings(); local n=0; IsInRaid=function() n=n+1; return false end; for i=1,1000 do assert(B:GroupSettings()==p and B:GroupPreference('groupNeed')==4) end; assert(n==0)")
case('Combat defers live group context transition',"B:GroupSettings('Party',true).groupNeed=4; B:GroupSettings('Raid',true).groupNeed=2; context='party'; refresh(); combat=true; safety('blocked'); context='raid'; B.events.scripts.OnEvent(nil,'GROUP_ROSTER_UPDATE'); assert(B:GroupPreference('groupNeed')==4); combat=false; safety('ready'); B.events.scripts.OnEvent(nil,'PLAYER_REGEN_ENABLED'); assert(B:GroupPreference('groupNeed')==2)")
case('Group controls refuse combat edits',"B:Options(); combat=true; B:GroupEditorSettings().groupNeed=5; assert(B:GroupPreference('groupNeed','Party')==3)")
case('Stale group action cannot survive configuration change',"context='party'; B.db.group=true; B.db.buffs.thorns=false; aura('player',5232,'Mark of the Wild'); refresh(); assert(B.action and B.action.target=='party1'); B:Options(); B:GroupEditorSettings().group=false; B.button.scripts.PreClick(nil,'LeftButton',true); assert(not B.action and not B.button.attrs.type1)")
test('Paladin assignment enablement is independent for Party and Raid',paladin+"BuffTap.db.blessingAssignments=false; BuffTap:SetBlessingPlanMode('Party',0,'same','bok'); assert(BuffTap:GroupPreference('blessingAssignments','Party') and not BuffTap:GroupPreference('blessingAssignments','Raid')); BuffTap:SetBlessingPlanMode('Raid',0,'same','bow'); assert(BuffTap:GroupPreference('blessingAssignments','Raid'))")
test('Paladin Greater thresholds and permission are independent',paladin+"BuffTap:Options(); local f=BuffTap.options; f.partyView.scripts.OnClick(); BuffTap:GroupEditorSettings().smartGroup=false; BuffTap:GroupEditorSettings().blessingNeed=4; f.raidView.scripts.OnClick(); assert(BuffTap:GroupEditorSettings().smartGroup and BuffTap:GroupEditorSettings().blessingNeed==2)")
test('Copy Party blessings enables the copied Raid plan',paladin+"BuffTap.db.blessingAssignments=false; BuffTap:SetBlessingPlanMode('Party',0,'same','bow'); BuffTap:CopyPartyBlessingsToRaid(); assert(BuffTap:BlessingPlan('Raid',0).blessing=='bow' and BuffTap:GroupPreference('blessingAssignments','Raid'))")
test('Paladin Follow Buffs affects only the viewed context',paladin+"BuffTap:SetBlessingPlanMode('Party',0,'same','bok'); BuffTap:SetBlessingPlanMode('Raid',0,'same','bow'); BuffTap:Options(); BuffTap.options.partyView.scripts.OnClick(); BuffTap.options.followBuffSettings.scripts.OnClick(); assert(not BuffTap:GroupPreference('blessingAssignments','Party') and BuffTap:GroupPreference('blessingAssignments','Raid'))")
for cls in ['DRUID','PALADIN','WARRIOR','HUNTER','ROGUE','WARLOCK','SHAMAN','MAGE','PRIEST']:
 for locale in ['enUS','deDE','frFR','esES','ptBR']:
  test('Separate group views '+cls+' '+locale,setup+"playerClass='"+cls+"'; B:InitDB(); B:Options(); local f=B.options; if playerClass=='PALADIN' then f.raidView.scripts.OnClick(); f.partyView.scripts.OnClick() else f.groupRaid.scripts.OnClick(); f.groupParty.scripts.OnClick() end; assert(B:EditingGroupContext()=='Party' and #f.tabs==11)",locale=locale)


test('Inactive Raid inherited blessing preview uses Raid Buffs preferences',paladin+"BuffTap.db.blessingAssignments=false; BuffTap.db.blessingClasses.WARRIOR=nil; BuffTap.db.blessingRaidDefaults=nil; BuffTap:InitDB(); BuffTap:SetSituationValue('raid','buffs','buffs',false,'bok'); BuffTap:SetSituationValue('raid','buffs','buffs',true,'bom'); BuffTap:SetSituationValue('raid','buffs','buffs',false,'bow'); BuffTap:Options(); BuffTap.options.raidView.scripts.OnClick(); assert(BuffTap.options.blessingRows[1].pick.text:find('Might') and BuffTap.situationCurrent~='raid')")
case('Reload keeps independent group thresholds and enablement',"B:GroupSettings('Party',true).groupNeed=4; B:GroupSettings('Party',true).group=false; B:GroupSettings('Raid',true).groupNeed=2; B:GroupSettings('Raid',true).group=true; B:InitDB(); assert(B:GroupPreference('groupNeed','Party')==4 and not B:GroupPreference('group','Party') and B:GroupPreference('groupNeed','Raid')==2 and B:GroupPreference('group','Raid'))")

